mapper.insert:
insert into goods (
    id, seller_id, category_id, title, detail, price, old_price, quality, location, status, cover, reason,
    audit_admin_id, audit_time, publish_time, view_count, favorite_count, lock_order_id, version,
    create_time, update_time, create_user, update_user
) values (
    #{id}, #{sellerId}, #{categoryId}, #{title}, #{detail}, #{price}, #{oldPrice}, #{quality}, #{location},
    #{status}, #{cover}, #{reason}, #{auditAdminId}, #{auditTime}, #{publishTime}, #{viewCount},
    #{favoriteCount}, #{lockOrderId}, #{version}, #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
)

mapper.select:
select id, seller_id, category_id, title, detail, price, old_price, quality, location, status, cover, reason, publish_time, view_count, favorite_count, create_time, update_time from goods where seller_id = #{sellerId}
and status = #{status}
order by update_time desc, id desc

select id, seller_id, category_id, title, price, old_price, quality, location, status, cover, reason, audit_admin_id, audit_time, publish_time, view_count, favorite_count, create_time, update_time from goods
and status = #{status}
and seller_id = #{sellerId}
and title like concat('%', #{title}, '%')
order by case when status = 1 then 0 else 1 end, update_time desc, id desc

select id, seller_id, category_id, title, price, old_price, quality, location, status, cover, publish_time, view_count, favorite_count from goods where status = 3
and category_id = #{categoryId}
and seller_id = #{sellerId}
and title like concat('%', #{title}, '%')
order by publish_time desc, id desc
